-- ===========================================================================
-- 068: the workspace reference on `forms` and `questions`, the installation-wide
-- `forms.slug` constraint, and at most one shared workspace.
--
-- Entirely generated by `drizzle-kit generate` from the control-plane schema
-- module. There is no hand-authored half, and the two things a reader might go
-- looking for are absent for a reason:
--
--   * **No grant block.** This migration creates no table, and a grant on a table
--     covers the columns added to it later, so `qcms_app_control`'s DML and each
--     `qcms_app_<env>`'s `SELECT` on `control`.`forms` already reach
--     `workspace_id`. The rule a new control-plane table follows (migration
--     0001's) does not apply to a column.
--   * **No backfill and no default on either `NOT NULL` column.** Green field
--     (Q22): there is no installation holding a form or a question for this to
--     fail against, and the column being `NOT NULL` with nothing to fall back on
--     is exactly criterion 1 - a form or a question cannot exist without exactly
--     one workspace. An operator holding a populated development database from
--     before this migration drops it and migrates a new one, which is the
--     instruction section 4a of `plan/environments-and-workspaces.md` already
--     gives for the re-baseline.
-- ===========================================================================
ALTER TABLE "control"."questions" ADD COLUMN "workspace_id" text NOT NULL;--> statement-breakpoint
ALTER TABLE "control"."forms" ADD COLUMN "workspace_id" text NOT NULL;--> statement-breakpoint
ALTER TABLE "control"."questions" ADD CONSTRAINT "questions_workspace_id_organization_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "control"."organization"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "control"."forms" ADD CONSTRAINT "forms_workspace_id_organization_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "control"."organization"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "organization_shared_uq" ON "control"."organization" USING btree ("isShared") WHERE "control"."organization"."isShared";--> statement-breakpoint
ALTER TABLE "control"."forms" ADD CONSTRAINT "forms_slug_unique" UNIQUE("slug");
